//! Parsing derive macro options with `darling`.

use development_tools_procedural_macro_helpers::MyDarlingMacro;

/// A trait implemented by the derive macro.
pub trait MyDarlingTrait {
    /// Prints a greeting.
    fn hello();
}

/// A struct that derives `MyDarlingMacro`.
#[derive(MyDarlingMacro)]
#[my_macro(name = "World")]
struct MyStruct;

/// Calls the method generated by the derive macro.
fn main() {
    <MyStruct as MyDarlingTrait>::hello();
}
// ANCHOR_END: example

/// Runs the example.
pub fn run() {
    main();
}

/// Verifies that parsed derive attributes reach the generated method.
#[test]
fn test() {
    main();
}
